def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MIN_SUPPLY = 15
    MAX_SUPPLY = 25

    supply = float(day_context['supply'])
    day = int(day_context['day'])
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    alive_opponents = []
    for oid, opp in opponents_status.items():
        if opp.get('alive'):
            alive_opponents.append(opp)

    if budget <= 0:
        return 0.0

    if not alive_opponents:
        return float(min(budget, 18.0))

    prev_bids = []
    urgent_opp = 0
    rich_opp = 0
    total_alive = 1
    for opp in alive_opponents:
        total_alive += 1
        if opp.get('budget', 0) >= 250:
            rich_opp += 1
        if opp.get('hp', 10) <= 3 or opp.get('no_water_days', 0) >= 1:
            urgent_opp += 1
        prev = opp.get('previous_trace') or {}
        bid = prev.get('bid')
        if bid is not None:
            try:
                prev_bids.append(float(bid))
            except Exception:
                pass

    highest_prev = max(prev_bids) if prev_bids else 0.0
    avg_prev = sum(prev_bids) / len(prev_bids) if prev_bids else 0.0

    supply_ratio = supply / float(WATER_REQ * total_alive)
    scarce = supply_ratio < 0.55
    moderate = supply_ratio < 0.8

    danger = 0
    if hp <= 2:
        danger += 3
    elif hp <= 4:
        danger += 2
    elif hp <= 6:
        danger += 1

    if no_water_days >= 2:
        danger += 3
    elif no_water_days >= 1:
        danger += 2

    if scarce:
        danger += 2
    elif moderate:
        danger += 1

    if urgent_opp >= 2:
        danger += 1

    if highest_prev >= 130:
        market = 'extreme'
    elif highest_prev >= 110:
        market = 'hot'
    elif highest_prev >= 80:
        market = 'warm'
    else:
        market = 'cool'

    if danger >= 5:
        bid = max(118.0, highest_prev + 3.0)
    elif danger >= 3:
        if market == 'extreme':
            bid = 96.0
        elif market == 'hot':
            bid = highest_prev + 1.5
        elif market == 'warm':
            bid = max(78.0, avg_prev + 2.0)
        else:
            bid = 72.0
    else:
        if market == 'extreme':
            bid = 22.0
        elif market == 'hot':
            bid = 34.0
        elif market == 'warm':
            bid = 46.0
        else:
            bid = 52.0

    if day >= 8:
        if hp <= 5:
            bid += 12.0
        else:
            bid += 4.0

    if rich_opp >= 2 and scarce:
        bid += 8.0

    if budget < 120:
        bid = min(bid, 0.55 * budget)
    elif budget < 200:
        bid = min(bid, 0.72 * budget)

    if hp >= 8 and no_water_days == 0 and market in ('extreme', 'hot') and not scarce:
        bid = min(bid, 28.0)

    bid = max(0.0, min(float(budget), float(bid)))
    return float(round(bid, 2))

def get_bid(day_context, my_status, opponents_status):
    DAILY_SALARY = 150
    WATER_REQ = 13
    supply = day_context['supply']
    day = day_context['day']
    budget = my_status['budget']
    hp = my_status['hp']
    no_water_days = my_status['no_water_days']

    alive_opponents = [o for o in opponents_status.values() if o['alive']]
    if not alive_opponents:
        return min(budget, DAILY_SALARY * 0.4)

    # Extract yesterday's max bid from alive opponents
    prev_bids = []
    for opp in alive_opponents:
        trace = opp.get('previous_trace', {})
        if trace and trace.get('bid') is not None:
            prev_bids.append(trace['bid'])

    max_prev_bid = max(prev_bids) if prev_bids else 0

    # Urgency: need water if hp low or consecutive no water days
    urgent = (hp <= 3) or (no_water_days >= 2)

    if urgent:
        # Must get water: outbid yesterday's max by 2, but cap at budget
        target = max(DAILY_SALARY * 0.8, max_prev_bid + 2)
        return min(budget, target)
    else:
        # Conservatively low, but still reasonable
        base = DAILY_SALARY * 0.35
        # If supply is low, increase a bit
        if supply < 18:
            base = DAILY_SALARY * 0.5
        return min(budget, base)
}

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 7
    DAILY_SALARY = 80

    strong_opponents_ids = ["Bob", "Cindy"]

    yesterday_strong_bids = []
    for opp_id in strong_opponents_ids:
        if opp_id in opponents_status and opponents_status[opp_id]['alive']:
            prev = opponents_status[opp_id].get('previous_trace', {})
            if prev and prev.get('bid') is not None:
                yesterday_strong_bids.append(prev['bid'])

    highest_prev_strong_bid = 0
    if yesterday_strong_bids:
        highest_prev_strong_bid = max(yesterday_strong_bids)

    available_water_units = int(day_context['supply'] // WATER_REQ)

    competitive_agents_count = 1 
    for opp_id in strong_opponents_ids:
        if opp_id in opponents_status and opponents_status[opp_id]['alive']:
            competitive_agents_count += 1

    my_current_hp = my_status['hp']
    my_current_budget = my_status['budget']

    bid = 0.0 # Initialize bid

    if my_current_hp <= 1 or my_status['no_water_days'] >= 1: # Critical HP or missed water yesterday
        if highest_prev_strong_bid > 0:
            bid = max(DAILY_SALARY * 1.7, highest_prev_strong_bid + 10)
        else:
            bid = DAILY_SALARY * 1.7 
    elif my_current_hp == 2: # Very low HP
        if highest_prev_strong_bid > 0:
            bid = max(DAILY_SALARY * 1.5, highest_prev_strong_bid + 5)
        else:
            bid = DAILY_SALARY * 1.5
    elif my_current_hp == 3: # Low HP
        if highest_prev_strong_bid > 0:
            bid = max(DAILY_SALARY * 1.3, highest_prev_strong_bid + 2)
        else:
            bid = DAILY_SALARY * 1.3
    else: # Healthy HP (hp > 3)
        if competitive_agents_count <= available_water_units:
            if highest_prev_strong_bid > 0:
                bid = max(DAILY_SALARY * 0.9, highest_prev_strong_bid * 0.95)
            else:
                bid = DAILY_SALARY * 0.9
        else:
            if highest_prev_strong_bid > 0:
                bid = max(DAILY_SALARY * 1.1, highest_prev_strong_bid + 1)
            else:
                bid = DAILY_SALARY * 1.1

    return min(my_current_budget, bid)

def get_bid(day_context, my_status, opponents_status):
